INSERT INTO dsl_history_diag_24ba0af6e88a.history_extrema_v1 SELECT 'stock-20060104-20260414-v1','306f333e28c82c9f2c634d8a1eb64eb49d3092937d8ca7d2742d96ecdcf21a95','6082c08809e679d4b9273b245a1c99c18bb906152313022c1bc830da36dc444d','2026-04-13',a.* FROM (SELECT b.mktcode,b.tgtcode,MAX(CASE WHEN b.bizdate='2026-04-13' THEN b.lowPrice END) AS low_current,MIN(b.lowPrice) AS low_min,MAX(b.lowPrice) AS low_max,MAX(CASE WHEN b.bizdate='2026-04-13' THEN b.highPrice END) AS high_current,MIN(b.highPrice) AS high_min,MAX(b.highPrice) AS high_max,MAX(CASE WHEN b.bizdate='2026-04-13' THEN b.closePrice END) AS close_current,MIN(b.closePrice) AS close_min,MAX(b.closePrice) AS close_max FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate<='2026-04-13' GROUP BY b.mktcode,b.tgtcode HAVING MAX(CASE WHEN b.bizdate='2026-04-13' THEN 1 ELSE 0 END)=1) a;
